{"operation":"bash","command":"cat <<'EOF' > /app/merge_users.py
import json
from datetime import datetime, date

import pandas as pd

FIELDS = ["name", "email", "created_date", "status"]
PRIORITY = ["source_a", "source_b", "source_c"]


def norm_status(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if not s:
        return None
    low = s.lower()
    if low in ("true", "1", "active", "yes"):
        return "active"
    if low in ("false", "0", "inactive", "no"):
        return "inactive"
    return s


def norm_date(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(v, (pd.Timestamp, datetime, date)):
        return pd.Timestamp(v).strftime("%Y-%m-%d")
    s = str(v).strip()
    if not s:
        return None
    try:
        return pd.Timestamp(s).strftime("%Y-%m-%d")
    except Exception:
        return s


def norm_uid(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    return int(float(str(v).strip()))


def norm_str(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    s = str(v).strip()
    return s if s else None


# ---------------- read sources ----------------
with open("/data/source_a/users.json") as f:
    a_rows = json.load(f)
a_df = pd.DataFrame(a_rows)
a_df = a_df.rename(columns={
    "id": "user_id",
    "full_name": "name",
    "email": "email",
    "registration_date": "created_date",
    "status": "status",
})

b_df = pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False, na_values=[""])
b_df = b_df.rename(columns={
    "user_id": "user_id",
    "name": "name",
    "email_address": "email",
    "created_at": "created_date",
    "is_active": "status",
})

c_df = pd.read_parquet("/data/source_c/users.parquet")
c_df = c_df.rename(columns={
    "userId": "user_id",
    "userName": "name",
    "email": "email",
    "joined": "created_date",
    "active": "status",
})

sources = {"source_a": a_df, "source_b": b_df, "source_c": c_df}

records = {}  # source -> {uid: {field: value}}
for src, df in sources.items():
    per_user = {}
    for _, row in df.iterrows():
        uid = norm_uid(row.get("user_id"))
        if uid is None:
            continue
        entry = per_user.setdefault(uid, {})
        if "name" in df.columns:
            entry["name"] = norm_str(row.get("name"))
        if "email" in df.columns:
            entry["email"] = norm_str(row.get("email"))
        if "created_date" in df.columns:
            entry["created_date"] = norm_date(row.get("created_date"))
        if "status" in df.columns:
            entry["status"] = norm_status(row.get("status"))
    records[src] = per_user

all_uids = sorted({uid for per_user in records.values() for uid in per_user})

merged_rows = []
conflicts = []
for uid in all_uids:
    out = {"user_id": int(uid)}
    for field in FIELDS:
        available = {}
        for src in PRIORITY:
            rec = records[src].get(uid)
            if rec is None:
                continue
            val = rec.get(field)
            if val is not None:
                available[src] = val
        if not available:
            out[field] = None
            continue
        selected = None
        for src in PRIORITY:
            if src in available:
                selected = available[src]
                break
        out[field] = selected
        distinct = set(available.values())
        if len(available) > 1 and len(distinct) > 1:
            conflict = {"user_id": int(uid), "field": field, "values": {}}
            for src in PRIORITY:
                if src in available:
                    conflict["values"][src] = available[src]
            conflict["selected"] = selected
            conflicts.append(conflict)
    merged_rows.append(out)

out_df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email", "created_date", "status"])
out_df["user_id"] = out_df["user_id"].astype("int64")
for col in ("name", "email", "created_date", "status"):
    out_df[col] = out_df[col].astype("object")

out_df.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2)

print(out_df.to_string())
print("----")
print(json.dumps(report, indent=2))
EOF
